local D = {["center_imp"] = {["Pelvis"] = {0.0, 8.0502, 0.1389}, ["SkirtFL"] = {-1.22785, 8.54735, -1.11765}, ["SkirtSL"] = {-1.5475, 8.33525, 0.0}, ["SkirtFR"] = {1.22785, 8.54735, -1.11765}, ["SkirtSR"] = {1.5475, 8.33525, 0.0}, ["Torso"] = {0.0, 10.625, -0.0518}, ["ShoulderPadL"] = {-2.2945, 11.62835, 0.025}, ["UpperArmL"] = {-2.1877, 10.3109, -0.025}, ["LowerArmL"] = {-2.64875, 7.7077, -0.1329}, ["ShoulderPadR"] = {2.2945, 11.62835, 0.025}, ["UpperArmR"] = {2.1877, 10.3109, -0.025}, ["LowerArmR"] = {2.6557, 7.7291, 0.0291}, ["UpperLegL"] = {-0.95, 7.125, -0.125}, ["LowerLegL"] = {-1.27095, 3.375, -0.025}, ["FootL"] = {-1.0, 0.825, -0.625}, ["UpperLegR"] = {0.95, 7.125, -0.125}, ["LowerLegR"] = {1.27095, 3.375, -0.025}, ["FootR"] = {1.0, 0.825, -0.625}, ["Backpack"] = {0.0, 10.825, 1.65}, ["WingL"] = {-1.3518, 8.99145, 2.5664}, ["WingR"] = {1.3518, 8.99145, 2.5664}, ["Head"] = {0.0, 12.6056, 0.11755}, ["SpikeL1"] = {-1.9, 10.7, 1.3}, ["SpikeR1"] = {1.9, 10.7, 1.3}, ["SpikeL2"] = {-1.9, 10.7, 2.0}, ["SpikeR2"] = {1.9, 10.7, 2.0}, ["GLCoverL"] = {-2.5682, 8.1323, -1.1514}, ["SaberHolsterL"] = {-0.4745, 12.95275, 1.50095}, ["RifleStowed"] = {0.0, 8.025, 1.9}, ["Rifle"] = {2.97195, 5.11125, -1.22735}, ["Grenade"] = {-2.60975, 6.95285, -1.40525}}, ["pivot"] = {["Pelvis"] = {0.0, 17.2, 0.0}, ["SkirtFL"] = {-1.1, 18.4, -1.9}, ["SkirtSL"] = {-2.7, 18.4, 0.0}, ["SkirtFR"] = {1.1, 18.4, -1.9}, ["SkirtSR"] = {2.7, 18.4, 0.0}, ["Torso"] = {0.0, 18.2, 0.0}, ["ShoulderPadL"] = {-4.0, 22.8, 0.0}, ["UpperArmL"] = {-4.0, 22.8, 0.0}, ["LowerArmL"] = {-4.68832, 18.45418, 0.0}, ["ShoulderPadR"] = {4.0, 22.8, 0.0}, ["UpperArmR"] = {4.0, 22.8, 0.0}, ["LowerArmR"] = {4.68832, 18.45418, 0.0}, ["UpperLegL"] = {-1.7, 16.6, 0.0}, ["LowerLegL"] = {-1.9, 10.4, -0.2}, ["FootL"] = {-2.0, 2.6, 0.0}, ["UpperLegR"] = {1.7, 16.6, 0.0}, ["LowerLegR"] = {1.9, 10.4, -0.2}, ["FootR"] = {2.0, 2.6, 0.0}, ["Backpack"] = {0.0, 21.4, 2.2}, ["WingL"] = {-2.2, 23.6, 3.2}, ["WingR"] = {2.2, 23.6, 3.2}, ["Head"] = {0.0, 24.0, -0.4}, ["SpikeL1"] = {-3.7, 21.4, 2.6}, ["SpikeR1"] = {3.7, 21.4, 2.6}, ["SpikeL2"] = {-3.7, 21.4, 4.0}, ["SpikeR2"] = {3.7, 21.4, 4.0}, ["GLCoverL"] = {-5.08326, 16.59988, -2.32714}, ["SaberHolsterL"] = {-0.8, 24.5, 2.9}, ["RifleStowed"] = {2.7, 16.6, 3.8}, ["Rifle"] = {5.59726, 12.71534, -1.02452}, ["Grenade"] = {-5.21952, 13.82178, -2.81046}}, ["R_upL"] = {{0.987688, 0.156434, 0.0}, {-0.156434, 0.987688, 0.0}, {0.0, 0.0, 1.0}}, ["R_lowL"] = {{0.987688, 0.151788, -0.037845}, {-0.156434, 0.95835, -0.238943}, {0.0, 0.241922, 0.970296}}, ["R_upR"] = {{0.987688, -0.156434, 0.0}, {0.156434, 0.987688, 0.0}, {0.0, 0.0, 1.0}}, ["R_lowR"] = {{0.987688, -0.154058, 0.027165}, {0.156434, 0.972683, -0.17151}, {0.0, 0.173648, 0.984808}}, ["fistR"] = {5.59725, 12.71534, -1.02452}, ["fistL"] = {-5.58386, 12.79991, -1.42734}, ["gripY"] = {-0.027165, 0.17151, -0.984808}, ["gripZ"] = {-0.154058, 0.972683, 0.173648}, ["foregrip"] = {6.43665, 7.41559, -2.38191}, ["muzzle"] = {7.09062, 3.2866, -4.83257}, ["muzzle2"] = {7.00632, 3.81883, -3.91506}, ["nozzles"] = {["NozzleUL"] = {-2.2, 24.7, 4.85}, ["NozzleDL"] = {-2.2, 23.8, 4.85}, ["NozzleUR"] = {2.2, 24.7, 4.85}, ["NozzleDR"] = {2.2, 23.8, 4.85}}, ["boostLight"] = {0.0, 24.2, 5.0}, ["legNozzles"] = {["BoostNozzleL"] = {-3.84593, 4.70748, 0.6}, ["BoostNozzleR"] = {3.84593, 4.70748, 0.6}}, ["tubes"] = {{-5.14747, 14.59628, -2.61693}, {-5.64132, 14.67449, -2.61693}}, ["coverSlide"] = {0.15179, 0.95835, 0.24192}, ["rootHeight"] = 17.25}
-- AELLO(LF-01) 템플릿 조립 1단계: ServerStorage 에 새 모델을 만들고 검사만(아직 교체 안 함). 10-26
local Proto = game.ReplicatedStorage.MechProto
local heavy = Proto.HeavyTemplate
local imp = workspace:FindFirstChild("Aero_r2b_C1_20261026")
assert(imp, "import missing")
local out = {}
local function V(t) return Vector3.new(t[1], t[2], t[3]) end
local function Rm(t) return CFrame.new(0, 0, 0, t[1][1], t[1][2], t[1][3], t[2][1], t[2][2], t[2][3], t[3][1], t[3][2], t[3][3]) end

-- 0) 가져온 자리 → 템플릿 좌표: 템플릿 = (가져온 위치 − O) × 2, 회전 없음 (가져오기가 이미 정면 −Z)
local O = imp.X_Pelvis.Position - V(D.center_imp.Pelvis)
local maxdev = 0
for name, c in pairs(D.center_imp) do
	local s = imp:FindFirstChild("X_" .. name)
	assert(s, "no X_" .. name)
	maxdev = math.max(maxdev, ((s.Position - V(c)) - O).Magnitude)
	assert(s.CFrame.Rotation:FuzzyEq(CFrame.new(), 1e-4), "rotated import " .. name)
end
table.insert(out, string.format("import offset spread %.5f", maxdev))
assert(maxdev < 0.01)

local old = game.ServerStorage:FindFirstChild("AeroTemplate_AELLO_build"); if old then old:Destroy() end
local m = Instance.new("Model"); m.Name = "AeroTemplate_AELLO_build"
local TEX = imp.X_Pelvis.TextureID
local refT = heavy.Torso
local P, baked = {}, {}
for name in pairs(D.center_imp) do
	if name ~= "Grenade" then
		local src = imp["X_" .. name]
		local p = src:Clone()
		p:ClearAllChildren()
		p.Name = name
		p.Size = src.MeshSize * 2
		p.CFrame = CFrame.new((src.Position - O) * 2)
		p.Anchored = false; p.CanCollide = false; p.CanQuery = refT.CanQuery; p.CanTouch = refT.CanTouch
		p.Massless = true; p.CastShadow = true; p.Material = refT.Material; p.CollisionGroup = "Default"
		local sa = refT.SurfaceAppearance:Clone(); sa.ColorMap = TEX; sa.Parent = p
		p.Parent = m
		P[name] = p; baked[name] = p.CFrame
	end
end
local hrp = heavy.HumanoidRootPart:Clone(); hrp.CFrame = CFrame.new(V(D.pivot.Pelvis)); hrp.Parent = m
P.HumanoidRootPart = hrp; baked.HumanoidRootPart = hrp.CFrame
local hum = heavy.Humanoid:Clone(); hum.HipHeight = D.rootHeight - hrp.Size.Y / 2; hum.Parent = m
m.PrimaryPart = hrp

-- 1) 관절(이름·부모는 중장갑 템플릿과 같은 규약). 팔: 어깨 C1 = R_up, 팔꿈치 C0 = R_up · C1 = R_low → Transform 0 = 팔 곧게
local Rup = { L = Rm(D.R_upL), R = Rm(D.R_upR) }
local Rlo = { L = Rm(D.R_lowL), R = Rm(D.R_lowR) }
local J = {}
local function joint(name, p0, p1, pivotOf, r0, r1, parent)
	local piv = V(D.pivot[pivotOf])
	local j = Instance.new("Motor6D"); j.Name = name
	j.Part0 = P[p0]; j.Part1 = P[p1]
	j.C0 = baked[p0]:Inverse() * CFrame.new(piv) * (r0 or CFrame.new())
	j.C1 = baked[p1]:Inverse() * CFrame.new(piv) * (r1 or CFrame.new())
	j.Parent = parent or P[p1]
	table.insert(J, j)
	return j
end
joint("Root", "HumanoidRootPart", "Pelvis", "Pelvis")
joint("Waist", "Pelvis", "Torso", "Torso")
joint("Neck", "Torso", "Head", "Head")
for _, s in ipairs({ "L", "R" }) do
	joint("Shoulder" .. s, "Torso", "UpperArm" .. s, "UpperArm" .. s, nil, Rup[s])
	joint("Elbow" .. s, "UpperArm" .. s, "LowerArm" .. s, "LowerArm" .. s, Rup[s], Rlo[s])
	joint("Pad" .. s, "Torso", "ShoulderPad" .. s, "ShoulderPad" .. s)
	joint("Hip" .. s, "Pelvis", "UpperLeg" .. s, "UpperLeg" .. s)
	joint("Knee" .. s, "UpperLeg" .. s, "LowerLeg" .. s, "LowerLeg" .. s)
	joint("Ankle" .. s, "LowerLeg" .. s, "Foot" .. s, "Foot" .. s)
	joint("SkirtJointF" .. s, "Pelvis", "SkirtF" .. s, "SkirtF" .. s)
	joint("SkirtJointS" .. s, "Pelvis", "SkirtS" .. s, "SkirtS" .. s)
	joint("WingJoint" .. s, "Backpack", "Wing" .. s, "Wing" .. s)
	joint("SpikeJoint" .. s .. "1", "Backpack", "Spike" .. s .. "1", "Spike" .. s .. "1")
	joint("SpikeJoint" .. s .. "2", "Backpack", "Spike" .. s .. "2", "Spike" .. s .. "2")
end
joint("Pack", "Torso", "Backpack", "Backpack")
joint("GLCoverJointL", "LowerArmL", "GLCoverL", "GLCoverL")
-- 라이플: 관절 틀 = 프로토 총 규약(Y = 총 위, Z = 총 뒤 → LookVector = 총구). 위치 = 오른 주먹 가운데. 쉬는 자세의 쥔 모양 그대로
local gY, gZ = V(D.gripY).Unit, V(D.gripZ).Unit
local gX = gY:Cross(gZ).Unit
gZ = gX:Cross(gY).Unit
local JR = CFrame.fromMatrix(V(D.fistR), gX, gY, gZ)
local grip = Instance.new("Motor6D"); grip.Name = "Grip"; grip.Part0 = P.LowerArmR; grip.Part1 = P.Rifle
grip.C0 = baked.LowerArmR:Inverse() * JR; grip.C1 = baked.Rifle:Inverse() * JR; grip.Parent = P.Rifle
table.insert(J, grip)

-- 2) 빔사벨(중장갑 것 복제: 손 칼 InHand) + 칼집 = 우리 SaberHolsterL(백팩에 묶음)
local saber = heavy.Saber:Clone()
for _, c in ipairs(saber.Holster:GetChildren()) do c:Destroy() end
P.SaberHolsterL.Parent = saber.Holster
P.SaberHolsterL:SetAttribute("Note", "등 위 왼쪽 칼자루(10-26 AELLO 안 A). Saber.Holster 안 = 손 칼이 보이면 숨음(MechClient setSaber)")
local hw = Instance.new("WeldConstraint"); hw.Part0 = P.Backpack; hw.Part1 = P.SaberHolsterL; hw.Parent = P.SaberHolsterL
saber.Parent = m
local hilt = saber.InHand.SaberHilt
local hSG = heavy.LowerArmL.SaberGrip
local sg = Instance.new("Motor6D"); sg.Name = "SaberGrip"; sg.Part0 = P.LowerArmL; sg.Part1 = hilt
sg.C0 = baked.LowerArmL:Inverse() * CFrame.new(V(D.fistL)) * Rlo.L
sg.C1 = hSG.C1
sg.Parent = P.LowerArmL
table.insert(J, sg)

-- 3) 허리 뒤 라이플(몸통에 묶음, 빔사벨 상태에서만 보임)
P.RifleStowed.Transparency = 1
P.RifleStowed:SetAttribute("Note", heavy.RifleStowed:GetAttribute("Note"))
local sw = Instance.new("WeldConstraint"); sw.Part0 = P.Torso; sw.Part1 = P.RifleStowed; sw.Parent = P.RifleStowed

-- 4) Transform 0 자세로 놓기(부모 → 자식 순서)
local order = { "Root", "Waist", "Neck", "PadL", "PadR", "ShoulderL", "ShoulderR", "ElbowL", "ElbowR", "GLCoverJointL", "Grip", "SaberGrip",
	"Pack", "WingJointL", "WingJointR", "SpikeJointL1", "SpikeJointL2", "SpikeJointR1", "SpikeJointR2",
	"HipL", "HipR", "KneeL", "KneeR", "AnkleL", "AnkleR", "SkirtJointFL", "SkirtJointFR", "SkirtJointSL", "SkirtJointSR" }
local byName = {}
for _, j in ipairs(J) do byName[j.Name] = j end
assert(#order == #J, "joint count " .. #order .. " vs " .. #J)
-- 사벨 부품: 중장갑 칼자루 기준 자리를 그대로(용접 끄고 옮기고 켬)
local offs = {}
for _, c in ipairs(heavy.Saber.InHand:GetChildren()) do
	if c:IsA("BasePart") then offs[c.Name] = heavy.Saber.InHand.SaberHilt.CFrame:Inverse() * c.CFrame end
end
local welds = {}
for _, w in ipairs(saber.InHand:GetDescendants()) do if w:IsA("WeldConstraint") then w.Enabled = false; table.insert(welds, w) end end
for _, n in ipairs(order) do
	local j = byName[n]
	j.Part1.CFrame = j.Part0.CFrame * j.C0 * j.C1:Inverse()
end
for _, c in ipairs(saber.InHand:GetChildren()) do
	if c:IsA("BasePart") and c ~= hilt then c.CFrame = hilt.CFrame * offs[c.Name] end
end
for _, w in ipairs(welds) do w.Enabled = true end

-- 5) 총구·왼손·노즐
local Rifle = P.Rifle
local mz = heavy.Rifle.Muzzle:Clone()
mz.CFrame = CFrame.new(baked.Rifle:PointToObjectSpace(V(D.muzzle))) * grip.C1.Rotation
mz.Parent = Rifle
local mz2 = Instance.new("Attachment"); mz2.Name = "Muzzle2"
mz2.CFrame = CFrame.new(baked.Rifle:PointToObjectSpace(V(D.muzzle2))) * grip.C1.Rotation; mz2.Parent = Rifle
Rifle:SetAttribute("ForeGrip", baked.Rifle:PointToObjectSpace(V(D.foregrip)))
for nm, pt in pairs(D.nozzles) do
	local a = heavy.Backpack[nm]:Clone()
	a.CFrame = CFrame.new(P.Backpack.CFrame:PointToObjectSpace(V(pt))); a.Parent = P.Backpack
end
local bl = heavy.Backpack.BoostLightAtt:Clone(); bl.CFrame = CFrame.new(P.Backpack.CFrame:PointToObjectSpace(V(D.boostLight))); bl.Parent = P.Backpack
for nm, pt in pairs(D.legNozzles) do
	local leg = P[(nm:sub(-1) == "L") and "LowerLegL" or "LowerLegR"]
	local a = heavy.Backpack.NozzleUL:Clone(); a.Name = nm
	a.CFrame = CFrame.new(leg.CFrame:PointToObjectSpace(V(pt))); a.Parent = leg
	a.Flame.EmissionDirection = Enum.NormalId.Bottom
end

-- 6) 속성
for k, v in pairs(heavy:GetAttributes()) do m:SetAttribute(k, v) end
m:SetAttribute("MechType", "Aero")
m:SetAttribute("Designation", "LF-01")
m:SetAttribute("DisplayName", "AELLO")
m:SetAttribute("RootHeight", D.rootHeight)
m:SetAttribute("StowPart", "Torso")
-- 거치대 총 교체(setGun) 때 등 총 자리: 중장갑 보정에 두 기체 허리 뒤 라이플 자리 차이(몸통 로컬)만 더함
local dH = heavy.Torso.CFrame:PointToObjectSpace(heavy.RifleStowed.Position)
local dA = P.Torso.CFrame:PointToObjectSpace(P.RifleStowed.Position)
m:SetAttribute("StowAdjust", CFrame.new(dA - dH) * heavy:GetAttribute("StowAdjust"))
m:SetAttribute("Source", "Aero_r2b_C1_20261026.glb x2 (10-26 LF-01 AELLO). 쉬는 자세 = 팔 벌림(STANCE 팔 9°). SurfaceAppearance = 가져온 팔레트 " .. TEX .. " + 발광 마스크 125885624850733(칸 6, 중장갑과 같은 그림), 세기 2")
m.ModelStreamingMode = Enum.ModelStreamingMode.Atomic
m.Parent = game.ServerStorage

-- 7) 검사
local maxe = 0
for _, j in ipairs(m:GetDescendants()) do
	if j:IsA("Motor6D") then
		local e = ((j.Part0.CFrame * j.C0 * j.C1:Inverse()).Position - j.Part1.Position).Magnitude
		maxe = math.max(maxe, e)
	end
end
local minY, maxY, nP = math.huge, -math.huge, 0
for _, d in ipairs(m:GetDescendants()) do
	if d:IsA("BasePart") and d.Transparency < 1 then
		nP += 1
		local c, s = d.CFrame, d.Size
		for _, sx in ipairs({ -1, 1 }) do for _, sy in ipairs({ -1, 1 }) do for _, sz in ipairs({ -1, 1 }) do
			local q = (c * CFrame.new(sx * s.X / 2, sy * s.Y / 2, sz * s.Z / 2)).Position
			minY = math.min(minY, q.Y); maxY = math.max(maxY, q.Y)
		end end end
	end
end
local conn = #hrp:GetConnectedParts(true)
table.insert(out, string.format("joints %d maxerr %.5f · visible parts %d · bbox y %.2f..%.2f · connected to HRP %d · HipHeight %.2f", #J, maxe, nP, minY, maxY, conn, hum.HipHeight))
table.insert(out, "ShoulderL C0 " .. tostring(byName.ShoulderL.C0.Position) .. " Grip C0 " .. tostring(grip.C0) .. " SaberGrip C0 pos " .. tostring(sg.C0.Position))
table.insert(out, "UpperArmL ori " .. tostring(P.UpperArmL.Orientation) .. " LowerArmL ori " .. tostring(P.LowerArmL.Orientation) .. " Rifle ori " .. tostring(Rifle.Orientation))
return table.concat(out, "\n")
